class MeshReconstructor:
    """Reconstruct 3D mesh from point clouds or images"""

    @staticmethod
    def pointcloud_to_mesh(points: np.ndarray, method: str = "poisson") -> trimesh.Trimesh:
        """Convert point cloud to mesh"""

        if method == "convex":
            return MeshReconstructor.convex_hull_mesh(points)
        elif method == "poisson":
            return MeshReconstructor.poisson_reconstruction(points)
        else:
            return MeshReconstructor.ball_pivot_mesh(points)

    @staticmethod
    def convex_hull_mesh(points: np.ndarray) -> trimesh.Trimesh:
        """Create mesh using convex hull"""
        try:
            hull = ConvexHull(points)
            mesh = trimesh.Trimesh(vertices=hull.points, faces=hull.simplices)
            return mesh
        except Exception as e:
            print(f"Convex hull failed: {e}, using point cloud directly")
            mesh = trimesh.Trimesh(vertices=points)
            return mesh

    @staticmethod
    def ball_pivot_mesh(points: np.ndarray, radius: float = 0.1) -> trimesh.Trimesh:
        """Create mesh using ball pivoting algorithm"""
        try:
            mesh = trimesh.Trimesh(vertices=points)
            # Try to create a closed mesh using voxelization
            mesh_voxel = mesh.voxelized(pitch=0.01)
            mesh_final = mesh_voxel.as_mesh()
            return mesh_final
        except Exception as e:
            print(f"Ball pivot failed: {e}")
            return MeshReconstructor.convex_hull_mesh(points)

    @staticmethod
    def poisson_reconstruction(points: np.ndarray, depth: int = 10) -> trimesh.Trimesh:
        """Reconstruct mesh from point cloud using Delaunay triangulation"""
        try:
            from scipy.spatial import Delaunay

            # Use Delaunay triangulation for 3D reconstruction
            # This creates a 3D mesh from the point cloud

            # For very large point clouds, subsample
            if len(points) > 5000:
                indices = np.random.choice(len(points), 5000, replace=False)
                points_sample = points[indices]
            else:
                points_sample = points

            # Compute Delaunay triangulation
            delaunay = Delaunay(points_sample)

            # Get convex hull simplices (surface faces)
            mesh = trimesh.Trimesh(vertices=delaunay.points, faces=delaunay.convex_hull)

            if len(mesh.vertices) > 0 and len(mesh.faces) > 0:
                return mesh
            else:
                return MeshReconstructor.convex_hull_mesh(points)

        except Exception as e:
            print(f"Delaunay triangulation failed: {e}, using convex hull")
            return MeshReconstructor.convex_hull_mesh(points)

    @staticmethod
    def voxel_to_mesh(voxel_grid: np.ndarray) -> trimesh.Trimesh:
        """Convert voxel grid to mesh"""
        voxel_grid = voxel_grid.astype(bool)
        mesh = trimesh.voxel.Voxel(voxel_grid).as_mesh()
        return mesh

    @staticmethod
    def smooth_mesh(mesh: trimesh.Trimesh, iterations: int = 5) -> trimesh.Trimesh:
        """Apply Laplacian smoothing to mesh"""
        try:
            # Use trimesh's built-in smoothing
            trimesh.smoothing.filter_laplacian(mesh, iterations=iterations, implicit_time_steps=1)
            return mesh
        except:
            return mesh

    @staticmethod
    def mesh_from_depth_map(depth_map: np.ndarray, fx: float = 500, fy: float = 500) -> trimesh.Trimesh:
        """Create mesh from depth map (camera calibration assumed)"""
        h, w = depth_map.shape

        # Create point cloud from depth
        x = np.arange(w)
        y = np.arange(h)
        xx, yy = np.meshgrid(x, y)

        # Normalize coordinates
        xx = (xx - w/2) / fx
        yy = (yy - h/2) / fy

        points = np.stack([xx * depth_map, yy * depth_map, depth_map], axis=-1)
        points = points.reshape(-1, 3)

        # Remove zero depth points
        points = points[depth_map.flatten() > 0]

        return MeshReconstructor.pointcloud_to_mesh(points)

