                mask = densities > density_threshold
                mesh_o3d.remove_vertices_by_mask(~mask)

            mesh_o3d.remove_duplicated_vertices()
            mesh_o3d.remove_degenerate_triangles()
            mesh_o3d.remove_non_manifold_edges()
