import trimesh
from pathlib import Path
import numpy as np

class MeshManager:
    """Manages mesh operations"""

    SUPPORTED_FORMATS = {
        '.stl': 'stl',
        '.obj': 'obj',
        '.ply': 'ply',
        '.gltf': 'gltf',
        '.glb': 'glb'
    }

    @staticmethod
    def load_mesh(file_path: str) -> trimesh.Trimesh:
        """Load a mesh from file"""
        file_path = Path(file_path)

        if not file_path.exists():
            raise FileNotFoundError(f"File not found: {file_path}")

        if file_path.suffix.lower() not in MeshManager.SUPPORTED_FORMATS:
            raise ValueError(f"Unsupported format: {file_path.suffix}")

        mesh = trimesh.load(str(file_path), process=True)

        # Ensure it's a single mesh
        if isinstance(mesh, trimesh.Scene):
            mesh = trimesh.util.concatenate(mesh.geometry.values())

        return mesh

    @staticmethod
    def save_mesh(mesh: trimesh.Trimesh, file_path: str) -> None:
        """Save mesh to file"""
        file_path = Path(file_path)

        if file_path.suffix.lower() not in MeshManager.SUPPORTED_FORMATS:
            raise ValueError(f"Unsupported format: {file_path.suffix}")

        file_path.parent.mkdir(parents=True, exist_ok=True)
        mesh.export(str(file_path))

    @staticmethod
    def scale_mesh(mesh: trimesh.Trimesh, scale_factor: float) -> trimesh.Trimesh:
        """Scale mesh by factor"""
        mesh.apply_scale(scale_factor)
        return mesh

    @staticmethod
    def center_mesh(mesh: trimesh.Trimesh) -> trimesh.Trimesh:
        """Center mesh at origin"""
        mesh.vertices -= mesh.center_mass
        return mesh

    @staticmethod
    def smooth_mesh(mesh: trimesh.Trimesh, iterations: int = 1) -> trimesh.Trimesh:
        """Apply Laplacian smoothing"""
        mesh = mesh.smooth_laplacian(iterations=iterations)
        return mesh

    @staticmethod
    def subdivide_mesh(mesh: trimesh.Trimesh, iterations: int = 1) -> trimesh.Trimesh:
        """Subdivide mesh for more detail"""
        for _ in range(iterations):
            mesh = mesh.subdivide()
        return mesh

    @staticmethod
    def decimate_mesh(mesh: trimesh.Trimesh, target_count: int) -> trimesh.Trimesh:
        """Reduce polygon count"""
        mesh.simplify_quadratic_mesh(target_count=target_count)
        return mesh

    @staticmethod
    def merge_meshes(meshes: list) -> trimesh.Trimesh:
        """Merge multiple meshes into one"""
        return trimesh.util.concatenate(meshes)

    @staticmethod
    def get_mesh_info(mesh: trimesh.Trimesh) -> dict:
        """Get mesh statistics"""
        return {
            'vertices': len(mesh.vertices),
            'faces': len(mesh.faces),
            'bounds': mesh.bounds.tolist(),
            'volume': mesh.volume,
            'surface_area': mesh.area,
            'is_watertight': mesh.is_watertight,
            'center': mesh.center_mass.tolist(),
            'extents': mesh.extents.tolist()
        }

    mesh = self._clean_mesh(mesh)

    if self._is_trivial_mesh(mesh):
        raise Exception("Fallback reconstruction still produced a trivial mesh")

    return mesh

def _clean_mesh(self, mesh: trimesh.Trimesh) -> trimesh.Trimesh:
    """Clean and smooth the mesh"""
    try:
        # Remove small disconnected components (keep only large ones)
        meshes = mesh.split()
        if len(meshes) > 1:
            # Sort by surface area and keep large components
            meshes_sorted = sorted(meshes, key=lambda m: m.area, reverse=True)

            # Keep largest mesh
            largest = meshes_sorted[0]
            largest_area = largest.area

            # Also keep components that are >5% of largest
            components_to_keep = [largest]
            for m in meshes_sorted[1:]:
                if m.area > largest_area * 0.05:  # Keep if >5% of main body
                    components_to_keep.append(m)

            if len(components_to_keep) > 1:
                mesh = trimesh.util.concatenate(components_to_keep)
            else:
                mesh = largest

        # Remove duplicate vertices
        if hasattr(mesh, 'merge_vertices'):
            mesh.merge_vertices()

        # Smooth the surface using simple vertex averaging
        if self.detail_level >= 2:
            # Use simple smoothing by averaging neighboring vertices
            mesh = self._smooth_mesh(mesh, iterations=2)

        return mesh

    except Exception as e:
        print(f"Mesh cleaning warning: {e}")
        return mesh

def _smooth_mesh(self, mesh: trimesh.Trimesh, iterations: int = 1) -> trimesh.Trimesh:
    """Apply smoothing to mesh vertices"""
    try:
        for _ in range(iterations):
            # Get adjacency information
            neighbors = [[] for _ in range(len(mesh.vertices))]

            for face in mesh.faces:
                for i in range(3):
                    v1 = face[i]
                    v2 = face[(i + 1) % 3]
                    if v2 not in neighbors[v1]:
                        neighbors[v1].append(v2)
                    if v1 not in neighbors[v2]:
                        neighbors[v2].append(v1)

            # Smooth vertices
            new_vertices = mesh.vertices.copy()
            for i, neighbors_list in enumerate(neighbors):
                if neighbors_list:
                    # Average with neighbors
                    avg = mesh.vertices[neighbors_list].mean(axis=0)
                    # Blend: keep 70% original, 30% average
                    new_vertices[i] = 0.7 * mesh.vertices[i] + 0.3 * avg

            mesh.vertices = new_vertices

        return mesh

    except Exception as e:
        print(f"Smoothing error: {e}")
        return mesh

def _validate_mesh(self, mesh: trimesh.Trimesh) -> trimesh.Trimesh:
    """Validate and normalize mesh"""
    try:
        # Ensure mesh is valid
        mesh.process(validate=True)

        # Get mesh bounds
        bounds = mesh.bounds
        sizes = bounds[1] - bounds[0]

        # If mesh is extremely small, it likely failed
        if np.max(sizes) < 0.1:
            raise Exception("Generated mesh is too small - likely generation failed")

        # Center mesh at origin
        mesh.vertices -= mesh.center_mass

        return mesh

    except Exception as e:
        print(f"Mesh validation warning: {e}")
        return mesh
